from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..validators import IsString, IsOneOf
from ..converter import to_bool


class UserManagementInterface(BaseInterface):

    def change_local_account_state(self, account_type, enable, timeout=60, alias="default"):
        """Change local account state.

        :param string account_type: BtsSecurity, BtsApplication or BtsRead
        :param boolean enable: Should enable.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        enable = to_bool(enable)
        timeout = timestr_to_secs(timeout)
        IsOneOf("BtsSecurity", "BtsApplication", "BtsRead").check(account_type)
        self.store.get(alias).execute_procedure("changeLocalAccountState", {"accountType": account_type, "enable": enable}, timeout)

    def change_ssh_password(self, username, new_password, old_password, timeout=60, alias="default"):
        """Change SSH password.

        :param string username: Username.
        :param string new_password: New password.
        :param string old_password: Old password.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(username)
        IsString().check(new_password)
        IsString().check(old_password)

        parameters = {
            "username": username,
            "password": new_password,
            "oldUsername": username,
            "oldPassword": old_password,
        }
        self.store.get(alias).execute_procedure("modifySshUser", parameters, timeout)

    def set_user_account(self, old_username, old_password, new_username=None, new_password=None, delete_flag=None, timeout=60,
                         alias="default"):
        """Set user account.

        :param string old_username: Old username.
        :param string old_password: Old password.
        :param string new_username: New username.
        :param string new_password: New password.
        :param bool delete_flag: Delete flag.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(old_username)
        IsString().check(old_password)

        parameters = {
            "oldUsername": old_username,
            "oldPassword": old_password
        }

        if new_username is not None:
            IsString().check(new_username)
            parameters["username"] = new_username

        if new_password is not None:
            IsString().check(new_password)
            parameters["password"] = new_password

        if delete_flag is not None:
            delete_flag = to_bool(delete_flag)
            parameters["deleteFlag"] = delete_flag

        self.store.get(alias).execute_procedure("userAccountSet", parameters, timeout)

    def get_user_login_info(self, timeout=60, alias="default"):
        """Get user login info."""
        timeout = timestr_to_secs(timeout)
        parameters = {}

        return self.store.get(alias).execute_infomodel_request("getUserLoginInfo", parameters, timeout)
